// ── Demonstrating cache effects through access patterns ─────────
// (In a real environment you would use performance.now() or perf counters;
//  this simulates the latency model conceptually)

const SIZE = 1024 * 1024; // 1M integers = 4 MB
const arr = new Int32Array(SIZE);

// Fill array
for (let i = 0; i < SIZE; i++) arr[i] = i;

// SEQUENTIAL (cache-friendly): accesses arr[0], arr[1], arr[2] ...
// Each cache line (64 bytes = 16 ints) is fetched once, then 15 more hits
function sumSequential() {
  let sum = 0;
  for (let i = 0; i < SIZE; i++) sum += arr[i];
  return sum;
}

// STRIDE-16 (cache-unfriendly): accesses arr[0], arr[16], arr[32] ...
// Every access is in a different cache line — 16x more cache misses!
function sumStride16() {
  let sum = 0;
  for (let i = 0; i < SIZE; i += 16) sum += arr[i];
  return sum;
}

// RANDOM (worst case): accesses arr[random] — cache hit rate near 0
const indices = Array.from({length: SIZE/16}, (_, i) => i).sort(() => Math.random()-0.5);
function sumRandom() {
  let sum = 0;
  for (const idx of indices) sum += arr[idx * 16];
  return sum;
}

// Measure
const t = (fn) => { const s = Date.now(); fn(); return Date.now() - s; };
console.log('Sequential ms:', t(sumSequential));  // e.g.  5 ms
console.log('Stride-16 ms:', t(sumStride16));     // similar — smaller n
console.log('Random ms:', t(sumRandom));           // much slower

