// ── Measuring working set effects (Node.js, allocate large arrays) ──
// Concept: loop over arrays of different sizes and observe timing

const { performance } = require('perf_hooks');

function benchmarkWorkingSet(sizeInBytes) {
  const ints = sizeInBytes / 4;
  const arr = new Int32Array(ints);
  for (let i = 0; i < ints; i++) arr[i] = i;

  const ITERS = 100;
  const start = performance.now();
  let sum = 0;
  for (let iter = 0; iter < ITERS; iter++) {
    for (let i = 0; i < ints; i++) {
      sum += arr[i]; // sequential access — spatial locality
    }
  }
  const ms = performance.now() - start;
  const gbPerSec = (sizeInBytes * ITERS) / (ms / 1000) / 1e9;
  console.log(`${(sizeInBytes/1024).toFixed(0).padStart(8)} KB | ${ms.toFixed(1).padStart(8)} ms | ${gbPerSec.toFixed(2)} GB/s | ${sum > 0 ? 'ok' : ''}`);
}

console.log('Working set size | time | throughput');
benchmarkWorkingSet(32 * 1024);          //   32 KB  — fits in L1
benchmarkWorkingSet(256 * 1024);         //  256 KB  — fits in L2
benchmarkWorkingSet(8 * 1024 * 1024);    //    8 MB  — fits in L3
benchmarkWorkingSet(128 * 1024 * 1024);  //  128 MB  — RAM only
benchmarkWorkingSet(512 * 1024 * 1024);  //  512 MB  — RAM, larger

